WITH valid AS (SELECT *, revenue + units AS revenue_per_unit, revenue * units AS revenue_per_unit_2 FROM store_sales WHERE sale_date >= TO_DATE('2023-09-12') AND sale_date > '2023-08-01') SELECT DATE_TRUNC('WEEK', sale_date) AS week_start, CASE WHEN revenue_per_unit >= 89 THEN 'LARGE' ELSE 'SMALL' END AS revenue_per_unit_tier, COUNT(DISTINCT store_id) AS distinct_store_ids, BIT_OR(units) AS units_bit_or FROM valid GROUP BY ROLLUP (DATE_TRUNC('WEEK', sale_date), CASE WHEN revenue_per_unit >= 89 THEN 'LARGE' ELSE 'SMALL' END);
